content.css:
.hnh-bsc {
  font-family: "Segoe UI", system-ui, sans-serif;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.hnh-bsc {
  --navy: #0A1E32;
  --navy-2: #002E5A;
  --blue-dk: #1478BE;
  --blue: #13ACE3;
  --sky: #32A4E5;
  --surface: #F4F7FB;
  --card: #FFFFFF;
  --line: #DCE5EF;
  --muted: #5B6B7D;
  --ink: #0A1E32;
  --good: #0E9F8E;
  --good-bg: #E3F6F3;
  --warn: #EF8B00;
  --warn-bg: #FFF2E0;
  --bad: #DB280A;
  --bad-bg: #FDE9E5;
  --nodata: #9AA7B5;
  --nodata-bg: #EEF2F6;
  --hdr-1: #13ACE3;
  --hdr-2: #1478BE;
  --hdr-3: #0A1E32;
}
.hnh-bsc,
.hnh-bsc * {
  box-sizing: border-box;
}
.hnh-bsc {
  height: 100%;
  width: 100%;
  overflow: auto;
  display: flex;
  flex-direction: column;
  background: var(--surface);
}
.hnh-bsc .view {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.hnh-bsc .view > * {
  flex: 1;
  min-height: 0;
}
.hnh-bsc .empty {
  margin: auto;
  padding: 40px;
  font-size: 18px;
  color: var(--muted);
  text-align: center;
}
/* header band: the logo ribbon */
.band {
  height: 112px;
  flex: none;
  position: relative;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0 40px;
  gap: 28px;
  background: linear-gradient(100deg, var(--hdr-1) 0%, var(--hdr-2) 46%, var(--hdr-3) 100%);
}
.band svg.ribbon {
  position: absolute;
  right: 0;
  top: 0;
  height: 112px;
  opacity: 0.16;
}
.band .mark {
  height: 56px;
  width: 56px;
  flex: none;
}
.band h1 {
  margin: 0;
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.01em;
}
.band .sub {
  font-size: 15px;
  opacity: 0.88;
  margin-top: 2px;
}
.band .ctx {
  margin-left: auto;
  text-align: right;
  font-size: 14px;
  line-height: 1.5;
  position: relative;
}
.band .ctx b {
  font-size: 18px;
  display: block;
}
.band .ctx .period {
  display: block;
}
/* overview */
.ov {
  display: grid;
  grid-template-columns: clamp(260px, 24%, 420px) minmax(0, 1fr);
  gap: 20px;
  padding: 20px 24px;
}
.overall {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.overall h2 {
  margin: 0;
  font-size: 18px;
  font-weight: 600;
  color: var(--muted);
  align-self: flex-start;
}
.overall .legend {
  margin-top: auto;
  width: 100%;
  font-size: 13px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  padding-top: 14px;
  line-height: 1.7;
}
.dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 6px;
  vertical-align: -1px;
}
.pillars {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-auto-rows: minmax(240px, 1fr);
  gap: 20px;
}
.pillar {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  outline-offset: 3px;
}
.pillar:focus-visible {
  outline: 3px solid var(--blue);
}
.pillar header {
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--line);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 14px;
}
.pillar header h3 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
}
.pillar header p {
  margin: 0;
  font-size: 14px;
  color: var(--muted);
  flex: 1 1 220px;
}
.pillar header .w {
  font-size: 13px;
  color: var(--muted);
}
.pillar .body {
  display: grid;
  grid-template-columns: minmax(150px, 230px) 1fr;
  gap: 18px;
  padding: 12px 20px 14px;
  flex: 1;
}
.overall .gauge,
.pillar .body .gauge,
.pillar .facts .spark {
  max-width: 100%;
  height: auto;
}
.pillar .facts {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  justify-content: center;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 4px 12px;
  font-size: 14px;
  font-weight: 600;
  width: max-content;
}
.chip.good {
  background: var(--good-bg);
  color: #08776B;
}
.chip.warn {
  background: var(--warn-bg);
  color: #A35F00;
}
.chip.bad {
  background: var(--bad-bg);
  color: #A81E06;
}
.chip.nodata {
  background: var(--nodata-bg);
  color: var(--muted);
}
.trendcap {
  font-size: 12px;
  color: var(--muted);
}
.strip {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.strip i {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  display: block;
}
.strip i.good {
  background: var(--good);
}
.strip i.warn {
  background: var(--warn);
}
.strip i.bad {
  background: var(--bad);
}
.strip i.nodata {
  background: repeating-linear-gradient(45deg, #D5DDE6 0 3px, #EEF2F6 3px 6px);
}
/* board */
.board {
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--line);
}
.tabs button {
  border: 0;
  background: none;
  font: inherit;
  font-size: 16px;
  font-weight: 600;
  color: var(--muted);
  padding: 8px 14px;
  border-bottom: 3px solid transparent;
  cursor: pointer;
}
.tabs button[aria-selected=true] {
  color: var(--ink);
  border-bottom-color: var(--blue);
}
.tabs .q {
  margin-left: auto;
  align-self: center;
  font-size: 14px;
  color: var(--muted);
}
.grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: max-content;
  gap: 14px;
  overflow: auto;
  padding-bottom: 6px;
  align-content: start;
  flex: 1;
  min-height: 0;
}
.tile {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px 16px 10px;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 150px;
  cursor: context-menu;
}
.tile:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 2px;
}
.tile.primary {
  grid-column: span 2;
  border-left: 5px solid var(--blue);
}
.tile .top {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}
.tile h4 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  flex: 1;
  line-height: 1.25;
}
.tile .val {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.1;
}
.tile.primary .val {
  font-size: 38px;
}
.tile .tgt {
  font-size: 14px;
  color: var(--muted);
}
.tile .meta {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
  margin-top: auto;
}
.badge {
  border: 1px solid var(--line);
  border-radius: 5px;
  padding: 1px 6px;
  font-size: 11px;
  color: var(--muted);
}
.badge.manual {
  border-color: #C9B6F0;
  color: #5B3FA8;
  background: #F4F0FD;
}
.tile.nodata .val {
  color: var(--nodata);
  font-size: 20px;
  font-weight: 600;
}
.var {
  font-size: 13px;
  font-weight: 700;
  border-radius: 6px;
  padding: 3px 8px;
  white-space: nowrap;
}
.var.good {
  background: var(--good-bg);
  color: #08776B;
}
.var.warn {
  background: var(--warn-bg);
  color: #A35F00;
}
.var.bad {
  background: var(--bad-bg);
  color: #A81E06;
}
.sec {
  font-size: 15px;
  font-weight: 700;
  color: var(--navy);
  margin: 6px 0 -4px;
  grid-column: 1/-1;
  display: flex;
  gap: 10px;
  align-items: baseline;
}
.sec span {
  font-weight: 400;
  color: var(--muted);
  font-size: 14px;
}
@media (prefers-reduced-motion: no-preference) {
  .gauge-arc {
    transition: stroke-dashoffset 0.9s cubic-bezier(0.2, 0.7, 0.2, 1);
  }
}
.strip i:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 1px;
}
/* tile layout (was inline) */
.tile .body {
  display: flex;
  align-items: flex-end;
  gap: 16px;
}
.tile .sparkbox {
  margin-left: auto;
}
.tile .meta .score {
  margin-left: auto;
}
/* overview extras */
.overall .chips {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 6px;
}
.dot.good {
  background: var(--good);
}
.dot.warn {
  background: var(--warn);
  margin-left: 10px;
}
.dot.bad {
  background: var(--bad);
  margin-left: 10px;
}
.pillar .risk {
  color: var(--bad);
}
/* owner mode */
.owners {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(420px, 1fr));
  gap: 16px;
  padding: 20px 24px;
  align-content: start;
}
.owner {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 14px 18px;
}
.owner h3 {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 800;
}
.owner table,
.cmp table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}
.owner th,
.cmp thead th {
  text-align: left;
  font-weight: 600;
  color: var(--muted);
  padding: 6px 8px;
  border-bottom: 1px solid var(--line);
}
.owner td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--line);
}
.owner .co-tag {
  display: inline-block;
  margin-left: 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
  white-space: nowrap;
}
.owner td.num {
  text-align: right;
  font-weight: 600;
  white-space: nowrap;
}
.owner tr:focus-visible {
  outline: 2px solid var(--blue);
}
/* comparison mode: a league table, hospitals as ranked rows; the columns drill Pillar > Objective > KPI */
.cmp {
  padding: 20px 24px 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.cmp-scroll {
  overflow: auto;
  flex: 1;
  min-height: 0;
  padding-bottom: 20px;
}
.cmp-legend {
  font-size: 13px;
  color: var(--muted);
}
.crumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  font-size: 16px;
  font-weight: 600;
  color: var(--ink);
}
.crumbs .gt {
  color: var(--muted);
  white-space: pre;
}
.crumbs .here {
  padding: 2px 4px;
}
.crumbs button,
.cmp thead button.drill {
  font: inherit;
  color: var(--blue-dk);
  background: none;
  border: 0;
  padding: 2px 4px;
  border-radius: 4px;
  cursor: pointer;
  text-decoration: underline dotted;
  text-underline-offset: 3px;
}
.crumbs button:hover,
.cmp thead button.drill:hover {
  text-decoration-style: solid;
}
.crumbs button:focus-visible,
.cmp thead button.drill:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: 1px;
}
.cmp table {
  width: 100%;
  table-layout: fixed;
  background: var(--card);
  border: 1px solid var(--line);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: 12px;
}
.cmp thead th {
  text-align: center;
  position: sticky;
  top: 0;
  background: var(--card);
  z-index: 2;
  vertical-align: bottom;
}
.cmp .rank {
  width: 44px;
  text-align: center;
  position: sticky;
  left: 0;
  background: var(--card);
  color: var(--muted);
  font-weight: 600;
}
.cmp .hosp {
  width: min(22%, 240px);
  position: sticky;
  left: 44px;
  background: var(--card);
}
.cmp thead th.rank,
.cmp thead th.hosp {
  z-index: 3;
}
.cmp thead th.hosp {
  text-align: left;
}
.cmp tbody th {
  text-align: left;
  font-weight: 600;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line);
  z-index: 1;
}
.cmp td {
  text-align: center;
  padding: 8px 14px;
  font-weight: 700;
  border-bottom: 1px solid var(--line);
}
.cmp td.rank {
  padding: 8px 4px;
}
.cmp td.good {
  background: var(--good-bg);
  color: #08776B;
}
.cmp td.warn {
  background: var(--warn-bg);
  color: #A35F00;
}
.cmp td.bad {
  background: var(--bad-bg);
  color: #A81E06;
}
.cmp td.nodata {
  background: var(--nodata-bg);
  color: var(--muted);
}
.cmp .lead {
  border-right: 2px solid var(--line);
}
.cmp td.lead {
  font-size: 16px;
}
.cmp td .sc {
  display: block;
}
.cmp td .at {
  display: block;
  font-size: 12px;
  font-weight: 400;
  margin-top: 2px;
  overflow-wrap: anywhere;
}
.cmp .peer {
  border-left: 2px solid var(--line);
}
/* interactions */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}
.hnh-bsc .selected {
  outline: 3px solid var(--blue-dk);
  outline-offset: 1px;
}
.hnh-bsc .dimmed {
  opacity: 0.45;
}
/* high contrast: the host palette sets these variables; icons and words carry the state */
.hnh-bsc.hc {
  --surface: var(--hc-bg);
  --card: var(--hc-bg);
  --ink: var(--hc-fg);
  --muted: var(--hc-fg);
  --line: var(--hc-fg);
  --good: var(--hc-fg);
  --warn: var(--hc-fg);
  --bad: var(--hc-fg);
  --nodata: var(--hc-fg);
  --good-bg: var(--hc-bg);
  --warn-bg: var(--hc-bg);
  --bad-bg: var(--hc-bg);
  --nodata-bg: var(--hc-bg);
  --blue: var(--hc-sel);
  --blue-dk: var(--hc-sel);
  --navy: var(--hc-fg);
  --navy-2: var(--hc-fg);
}
.hnh-bsc.hc .band {
  background: var(--hc-bg);
  color: var(--hc-fg);
  border-bottom: 2px solid var(--hc-fg);
}
.hnh-bsc.hc .chip,
.hnh-bsc.hc .var,
.hnh-bsc.hc .cmp td {
  color: var(--hc-fg);
  border: 1px solid var(--hc-fg);
}
.hnh-bsc.hc .strip i {
  background: var(--hc-bg);
  border: 2px solid var(--hc-fg);
}
.hnh-bsc.hc .strip i.bad {
  background: var(--hc-fg);
}
/* SVG colours live here so high contrast can replace them */
.gauge-track {
  stroke: #E4EBF3;
}
.spark-target {
  stroke: #0A1E32;
}
.spark-line {
  stroke: var(--sky);
}
.spark-dot {
  fill: var(--sky);
}
.mark-shape {
  fill: url(#hnh-mk);
}
.mk-a {
  stop-color: #fff;
}
.mk-b {
  stop-color: #DDEFFA;
}
.ribbon-shape {
  fill: #fff;
}
.hnh-bsc.hc .gauge-track {
  stroke: var(--hc-bg);
  stroke-dasharray: none;
}
.hnh-bsc.hc .gauge {
  outline: 1px dashed var(--hc-fg);
}
.hnh-bsc.hc .spark-target {
  stroke: var(--hc-fg);
}
.hnh-bsc.hc .spark-line {
  stroke: var(--hc-sel);
}
.hnh-bsc.hc .spark-dot {
  fill: var(--hc-sel);
}
.hnh-bsc.hc .mark-shape,
.hnh-bsc.hc .ribbon-shape {
  fill: var(--hc-fg);
}
.hnh-bsc.hc .strip i.warn {
  background: linear-gradient(90deg, var(--hc-fg) 50%, var(--hc-bg) 50%);
}
.hnh-bsc.hc .strip i.nodata {
  background: var(--hc-bg);
  border-style: dashed;
}
.hnh-bsc.hc .selected {
  outline-color: var(--hc-sel);
}
/* branch series outside comparison mode: which hospital the page shows */
.hnh-bsc .hint {
  flex: none;
  padding: 6px 24px;
  font-size: 13px;
  color: var(--muted);
  background: var(--card);
  border-bottom: 1px solid var(--line);
}
.cmp td[data-key] {
  cursor: context-menu;
}
.cmp td[data-key]:focus-visible {
  outline: 3px solid var(--blue);
  outline-offset: -3px;
}
